// ScoreRequest Exactly one of `address` or `origin` must be provided; the API returns 400 if neither or both are set. Deliberately not expressed as a `oneOf` in this schema — with `oapi-codegen`, `oneOf` produces a wrapper type requiring `AsX`/`FromX`/`MergeX` accessor methods rather than a flat struct, which is worse ergonomics than a plain optional-pointer field validated in the handler. Same rule applies to `destination` vs. `destinationCoordinates`; if omitted entirely, the commute factor is hidden and weights renormalize across the remaining 8 factors.
type ScoreRequest struct {
	// Address Raw address to geocode before scoring. Mutually exclusive with `origin`.
	Address *string `json:"address,omitempty"`

	// AddressHint Optional raw address text to accompany `origin`, used only for `S_solar`'s street-facing orientation inference — it has no effect on which coordinate is actually scored, and never triggers a geocoding call. Lets a client that already resolved `origin` from its own prior /api/v1/geocode call (and so has the matching address text on hand) get real orientation inference without paying for a second, redundant geocode of that same address just to recover the string `address` would have provided. Ignored when `address` is set (orientation already infers from `address` directly in that case).
	AddressHint *string `json:"addressHint,omitempty"`

	// Destination Optional workplace/destination address for the custom commute factor.
	Destination *string `json:"destination,omitempty"`

	// DestinationCoordinates Pre-resolved destination coordinates. Mutually exclusive with `destination`.
	DestinationCoordinates *Coordinates `json:"destinationCoordinates,omitempty"`

	// Origin Pre-resolved origin coordinates from a prior /api/v1/geocode call. Mutually exclusive with `address`.
	Origin *Coordinates `json:"origin,omitempty"`

	// Unit Optional unit-level metadata powering the solar exposure factor.
	Unit *UnitMetadata `json:"unit,omitempty"`

	// Weights Optional per-factor weight overrides (0-100). Any omitted factor falls back to preset defaults; active weights are dynamically renormalized so they sum to 100%.
	Weights *WeightOverrides `json:"weights,omitempty"`
}

